import{z as s,x as n,o as e,c as p,q as o,j as i,D as E,d as t,s as r,S as A,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"多任务代理","description":"","frontmatter":{"title":"多任务代理","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/multitask-holmstrom.md","filePath":"econ/multitask-holmstrom.md","lastUpdated":1791063341000}'),m={name:"econ/multitask-holmstrom.md"};function _(d,a,C,c,h,b){const l=n("Mermaid");return e(),p("div",null,[a[2]||(a[2]=o('<h1 id="多任务代理" tabindex="-1">多任务代理 <a class="header-anchor" href="#多任务代理" aria-label="Permalink to &quot;多任务代理&quot;">​</a></h1><div class="epigraph"><p>对易测任务付强激励，会把努力从难测任务上抽走；任务挤出是激励相容的向量性质，不是偏好变懒。</p><footer>—— Holmström and Milgrom, Multitask Principal–Agent Analyses, Journal of Law, Economics, &amp; Organization, 1991</footer></div><p><a href="/econ/principal-agent">上一课</a>把单任务写成 IC–IR 规划，似然比进入工资。缺口是行动是向量：教学与科研、产量与质量、当期利润与维护。只对其中一维付 \\(\\beta\\)，其余维若更难测，努力会搬家。本课钉挤出与低能激励，不把显示原理写成下一课，也不重写单任务的 \\(1/u&#39;=\\lambda+\\mu(1-f_L/f_H)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代理人选 \\(a=(a_1,\\dots,a_k)\\)，成本 \\(c(a)\\) 在任务间凸（努力预算或注意力）。可验证信号 \\(x_i=a_i+\\varepsilon_i\\)，噪声可以极不对称：\\(a_1\\) 几乎可测，\\(a_2\\) 几乎不可测。线性教具（指数效用、正态噪声的 Holmström–Milgrom 极限）里，合同 \\(w=\\alpha+\\sum\\beta_i x_i\\)。单任务时 \\(\\beta\\) 随信噪比升；多任务时，对任务 1 的高 \\(\\beta_1\\) 会通过 \\(c_{12}\\) 降低 \\(a_2\\)。若 \\(a_2\\) 对委托人很重要（质量、合规、资产保养），最优可能把 \\(\\beta_1\\) 也压低——故意用低能激励，以免产量挤掉质量。</p><p>极端：某维完全不可测，\\(\\beta_2=0\\)。若任务完全替代，最优常是 \\(\\beta_1=0\\)，固定工资，靠投入监管或索取权改写（把难测任务变成代理人的资产）。这与「激励越强越好」相反。</p><p><span class="marginnote">直觉类比：只按升学率给老师发奖金，「刷题」就会顶掉备课；校长若测不了「有没有讲懂」，常常索性连升学率奖金也压低。强激励没有失灵，是它顺带把没人付钱的那一维打低了。</span></p><h3 id="挤出不是道德说教" tabindex="-1">挤出不是道德说教 <a class="header-anchor" href="#挤出不是道德说教" aria-label="Permalink to &quot;挤出不是道德说教&quot;">​</a></h3><p>\\(c_{12}\\gt 0\\) 时，提高 \\(a_1\\) 的边际成本含 \\(a_2\\)。IC 是一阶条件向量，不是一个不等式。单任务规划把其他维的努力当常数，会高估 \\(\\beta_1\\) 的好处。</p><p><span class="marginnote">原文同时谈资产所有权与工作设计：把互补任务捆给同一人、把替代且可测性差异大的任务拆开。本课只钉激励挤出；所有权是同一套 IC 的另一件工具。</span></p><p>可测性差异越大，越要用低 \\(\\beta\\) 或拆任务。 互补任务（\\(c_{12}\\lt 0\\)）则强激励可以带动另一维，捆绑有好处。 主观评价能补难测维，但引入讨好与再谈判，本课不写。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：两任务、线性合同、凸成本。先写代理人 FOC：\\(\\beta=c&#39;(a)\\) 的向量式。再代入委托人目标，看 \\(\\sigma_2^2\\to\\infty\\) 时 \\(\\beta_1\\) 是否被压向零。对照：若能把任务 2 独立交给另一代理人，挤出消失，但协作成本另计。</p><p><span class="marginnote">术语翻译：\\(c_{12}\\gt 0\\) 就是「两项任务在抢同一份精力」——多刷一单元产量，备课的边际成本跟着涨；\\(c_{12}\\lt 0\\) 则是互补，比如讲课顺带磨了讲义。判断挤出不靠道德直觉，只看这个交叉导数的符号。</span></p>',14)),(e(),i(A,null,{default:E(()=>[r(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PA%5B%22%E5%8D%95%E4%BB%BB%E5%8A%A1%EF%BC%9A%CE%B2%20%E9%9A%8F%E4%BF%A1%E5%99%AA%E6%AF%94%22%5D%20--%3E%20MT%5B%22%E8%A1%8C%E5%8A%A8%E6%98%AF%E5%90%91%E9%87%8F%22%5D%0A%20%20MT%20--%3E%20SUB%5B%22%E4%BB%BB%E5%8A%A1%E6%9B%BF%E4%BB%A3%22%5D%0A%20%20MEAS%5B%22%E4%B8%80%E7%BB%B4%E9%9A%BE%E6%B5%8B%22%5D%20--%3E%20CROWD%5B%22%E5%BC%BA%20%CE%B21%20%E6%8C%A4%E5%87%BA%20a2%22%5D%0A%20%20CROWD%20--%3E%20LOW%5B%22%E6%9C%80%E4%BC%98%EF%BC%9A%E4%BD%8E%E8%83%BD%E6%BF%80%E5%8A%B1%E6%88%96%E6%8B%86%E4%BB%BB%E5%8A%A1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[t("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"每一块 \\(\\beta_i\\) 买的是 \\(a_i\\)，但成本函数把各 \\(a_j\\) 连在一起。委托人无法只对 \\(a_1\\) 付报酬而不改 \\(a_2\\) 的影子价格。单任务里噪声大则少买激励；多任务里，即使任务 1 噪声很小，只要它替代任务 2，仍可能少买。测量技术改进若只覆盖产量、不覆盖质量，福利可以下降——这是 1991 年论文相对 1979 年充足统计的转折：多一个信号不再无条件更好，因为它改变了任务间的相对价格。",-1)),(e(),i(A,null,{default:E(()=>[r(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%A4%E4%BB%BB%E5%8A%A1%E5%BD%BC%E6%AD%A4%E6%98%AF%E6%9B%BF%E4%BB%A3%E8%BF%98%E6%98%AF%E4%BA%92%E8%A1%A5%22%5D%20--%3E%7C%22%E4%BA%92%E8%A1%A5%2C%20%E4%BA%A4%E5%8F%89%E6%88%90%E6%9C%AC%E4%B8%BA%E8%B4%9F%22%7C%20B%5B%22%E5%BC%BA%E6%BF%80%E5%8A%B1%E6%8D%86%E7%BB%91%E7%BB%99%E5%90%8C%E4%B8%80%E4%BA%BA%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9B%BF%E4%BB%A3%2C%20%E4%BA%A4%E5%8F%89%E6%88%90%E6%9C%AC%E4%B8%BA%E6%AD%A3%22%7C%20M%5B%22%E4%B8%A4%E7%BB%B4%E5%8F%AF%E6%B5%8B%E6%80%A7%E6%8E%A5%E8%BF%91%E5%90%97%22%5D%0A%20%20M%20--%3E%7C%22%E6%8E%A5%E8%BF%91%22%7C%20HI%5B%22%E6%8C%89%E5%90%84%E8%87%AA%E4%BF%A1%E5%99%AA%E6%AF%94%E6%AD%A3%E5%B8%B8%E7%BB%99%20%CE%B2%22%5D%0A%20%20M%20--%3E%7C%22%E5%B7%AE%E5%BC%82%E6%82%AC%E6%AE%8A%22%7C%20LOW%5B%22%E5%8E%8B%E4%BD%8E%E5%8F%AF%E6%B5%8B%E7%BB%B4%E7%9A%84%20%CE%B21%22%5D%0A%20%20LOW%20--%3E%20OWN%5B%22%E6%88%96%E6%8B%86%E4%BB%BB%E5%8A%A1%20%2F%20%E6%8A%8A%E9%9A%BE%E6%B5%8B%E7%BB%B4%E6%94%B9%E6%88%90%E8%B5%84%E4%BA%A7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">常见误区：初学者以为测量越准、合同就该写得越细。多任务下只给产量装上高精度仪表，等于单方面给产量「降价」，质量被挤得更狠——1979 年的充足统计在这里失效，多一个信号可以更糟。</span></p><p>充足统计仍说：共同冲击该滤。多任务说：滤完之后，\\(\\beta\\) 的水平还要看挤出。两句话叠用，不是互相取消。有限责任会让某些维的惩罚更难，挤出更狠；本课不把下界再推一遍。工作设计是第三条路：把替代且可测性差的任务拆给不同的人，或把难测任务变成代理人拥有的资产，使 \\(a_2\\) 的回报不再经过工资 \\(\\beta\\)。激励强度、测量与所有权是同一套 IC 的三件工具。</p><p>可测性差异越大，越要用低 \\(\\beta\\) 或拆任务；互补任务则强激励可以带动另一维。 只改进产量测量、不覆盖质量，福利可以下降——多一个信号不再无条件更好。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>超过线性–正态，最优合同不必线性，挤出仍在：任何对易测维更敏感的 \\(w\\) 都会搬家努力。多代理人、团队、主观绩效，是后继文献。不要把多任务写成宏观多部门或限价簿多品种；那是别的摩擦。</p><p>后课默认：多任务下，对易测任务的强激励会挤出难测任务；最优常常是低能激励或任务捆绑/拆分。显示原理下一步把「任意间接规则」收成直接机制，不改变这组 IC 向量。</p><h3 id="测量只改进一维可以有害" tabindex="-1">测量只改进一维可以有害 <a class="header-anchor" href="#测量只改进一维可以有害" aria-label="Permalink to &quot;测量只改进一维可以有害&quot;">​</a></h3><p>单任务的信息量原则：有信息就该写进合同。多任务：只改进 \\(x_1\\) 的精度，等于只给任务 1 降价，挤出加剧。政策含义是同时测量或索性都不按绩效付。学校考试、医院吞吐量、警察开罚单，是同一几何。</p><p><span class="marginnote">Holmström–Milgrom 的线性极限来自连续时间指数–正态；课堂上用它读 \\(\\beta\\)，不把线性当成一般道德风险的最优形式。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>行动是向量时，IC 是向量；一维强激励会抽走其他维。</li><li>可测性不对称 ⇒ 低能激励或拆任务，而不是把 \\(\\beta_1\\) 开到最大。</li><li>多一个只覆盖一维的信号，不必更好。</li><li>单任务规划不能直接套到工作设计。</li><li>出处：Holmström and Milgrom, <em>JLEO</em> 1991。</li></ul>',11))])}const D=s(m,[["render",_]]);export{f as __pageData,D as default};
